def int_to_string(n):
  if n == 0:
    return "0"
  sign = "-" if n < 0 else ""
  n = abs(n)
  digits = []
  while n > 0:
    digits.append(str(n % 10))
    n //= 10
  return sign + "".join(digits[::-1])
